F=Fig('arrow189');t=F.t;line=F.line
paras=[];layout=[];blocks=[]
def add(e,u,p,kind='paragraph'):
 layout.append({'type':kind,'indices':[len(paras)]});paras.append(pair(e,u,p))
def visual(identity,fn):
 blocks.append({'id':identity,'svg':fn('en'),'svgUrdu':fn('ur'),'svgPashto':fn('ps')});layout.append({'type':'visual','blockId':identity})
K=lambda lang,*v:v[{'en':0,'ur':1,'ps':2}[lang]]
def flip(lang):
 s=F.start(220)+'<path d="M300 210 L300 50 L288 50 L308 20 L328 50 L316 50 L316 210 Z" fill="#43a047"/>'+t(270,120,'B₀',14)
 for y,d,lab in ((50,1,K(lang,'β state','β حالت','β حالت')),(180,-1,K(lang,'α state','α حالت','α حالت'))):
  s+=f'<circle cx="370" cy="{y}" r="14" fill="none" stroke="#222" stroke-width="1.5"/>'+line(370,y-22,370,y+22,1.5)+f'<path d="M364 {y+22*d-8*d} L370 {y+22*d} L376 {y+22*d-8*d} Z" fill="#222"/>'+t(420,y+4,lab,12)+line(450,y,500,y,1.5)
 s+='<path d="M490 175 Q540 115 490 55" fill="none" stroke="#222" stroke-width="1.5"/><path d="M484 62 L490 52 L496 64 Z" fill="#222"/>'+t(580,118,'hυ = ΔE',13)
 return s+'</svg>'
def nmr(lang):
 X=lambda d:760-d*68
 s=F.start(270)+'<rect x="80" y="20" width="700" height="190" fill="#e3f2fd" stroke="#555"/>'
 for k in range(0,21):d=k/2;s+=line(X(d),190,X(d),210,0.6,'#555')
 for d in range(0,11):s+=t(X(d),228,f'{d:.1f}' if d else '0',11)
 s+=line(80,205,780,205,1.5,'#c62828')
 for d,h in ((4.8,90),(3.5,170)):s+=line(X(d)-3,205,X(d),205-h,1.6)+line(X(d),205-h,X(d)+3,205,1.6)
 s+=line(X(0)-2,205,X(0),175,1.6)+line(X(0),175,X(0)+2,205,1.6)+t(X(0),168,'TMS',11)
 s+='<rect x="290" y="40" width="160" height="70" fill="#fff" stroke="#555"/>'+t(330,80,'H—O—',14)+t(380,80,'C',14)+t(405,80,'—H',14)+line(380,66,380,56)+t(380,52,'H',12)+line(380,86,380,96)+t(380,108,'H',12)
 s+=line(330,90,X(4.8),120,1,'#555')+line(395,100,X(3.5),40,1,'#555')
 s+=t(430,252,'δ (ppm)',12)
 return s+'</svg>'

